INSERT INTO questionnaire_block_translations (block_id, locale, title, intro)
VALUES ('ebe16265-e5e2-506d-a3ba-d47fd4a8117b', 'de', 'Blog & News', 'Damit der Blog nicht leer startet: Was gibt es schon, und worüber wollt ihr schreiben? Stichpunkte reichen.'),
       ('ebe16265-e5e2-506d-a3ba-d47fd4a8117b', 'en', 'Blog & news', 'So the blog doesn’t start empty: what already exists, and what do you want to write about? Bullet points are fine.'),
       ('235ed36b-aefc-563e-a367-5728833c51f3', 'de', 'Karriere & Stellen', 'Zeig, warum man gern bei euch arbeitet. Stichpunkte reichen, wir formulieren aus.'),
       ('235ed36b-aefc-563e-a367-5728833c51f3', 'en', 'Careers & vacancies', 'Show why people enjoy working for you. Bullet points are fine, we’ll write them up.'),
       ('7ed17f07-2459-5b73-86af-5c251de90800', 'de', 'Produkte & Preise', 'Hier geht es um Produkte und feste Pakete, die auf der Website stehen sollen. Bei vielen Produkten reicht eine Liste als Datei.'),
       ('7ed17f07-2459-5b73-86af-5c251de90800', 'en', 'Products & prices', 'This is about products and fixed packages that should appear on the website. If you have many products, a list as a file is enough.'),
       ('1831fa5f-9a87-59fb-8461-ff6ea0e2446f', 'de', 'Veranstaltungen & Termine', 'Leg für jede Veranstaltung, die auf der Website stehen soll, einen Eintrag an. Was noch nicht feststeht, reichst du später nach.'),
       ('1831fa5f-9a87-59fb-8461-ff6ea0e2446f', 'en', 'Events & dates', 'Add an entry for every event that should appear on the website. Anything not fixed yet can follow later.'),
       ('04e9c54a-37e2-52d8-a3a3-bf3e3cab6b1e', 'de', 'Downloads', 'Welche Dateien sollen Besucher herunterladen können? Zum Beispiel Preislisten, Formulare, Checklisten oder Broschüren.'),
       ('04e9c54a-37e2-52d8-a3a3-bf3e3cab6b1e', 'en', 'Downloads', 'Which files should visitors be able to download? For example price lists, forms, checklists or brochures.'),
       ('f684afa4-6240-58ae-b064-285b218cc75f', 'de', 'Newsletter', 'Damit sich Besucher gern eintragen: Was bekommen sie von euch?'),
       ('f684afa4-6240-58ae-b064-285b218cc75f', 'en', 'Newsletter', 'So visitors are happy to sign up: what do they get from you?'),
       ('bc93a0db-0c59-52ec-a5c8-543de26a4e52', 'de', 'Anfrageformulare', 'Leg für jedes besondere Formular einen Eintrag an. Das normale Kontaktformular musst du nicht eintragen.'),
       ('bc93a0db-0c59-52ec-a5c8-543de26a4e52', 'en', 'Enquiry forms', 'Add an entry for every special form. You don’t need to add the standard contact form.'),
       ('0c38f16e-fcda-50e2-99a0-37f73d5210d1', 'de', 'Kampagne & Anzeigen', 'Eine Kampagne funktioniert, wenn Anzeige und Seite dasselbe versprechen. Stichpunkte reichen.'),
       ('0c38f16e-fcda-50e2-99a0-37f73d5210d1', 'en', 'Campaign & ads', 'A campaign works when the ad and the page promise the same thing. Bullet points are fine.'),
       ('13002f10-39c1-50d7-919b-f2bf9e5a9d0b', 'de', 'Mehrsprachigkeit', 'Welche Sprachen die Website bekommt, steht im Angebot. Hier geht es darum, was es schon gibt und was je Sprache anders ist.'),
       ('13002f10-39c1-50d7-919b-f2bf9e5a9d0b', 'en', 'Multiple languages', 'The languages for the website are set in your quote. This is about what already exists and what differs per language.')
;
